def contains(value, lower, upper):
    return lower <= value < upper


def demo():
    return contains(8, 2, 8)

def last_or_none(items):
    if not items:
        return None
    return items[-1]


def demo():
    return [last_or_none([]), last_or_none([4])]

def snapshot(cart):
    return {"items": cart["items"]}


def demo():
    cart = {"items": ["pen"]}
    saved = snapshot(cart)
    cart["items"].append("book")
    return saved["items"]

def duplicate_row(row):
    first = dict(row)
    second = dict(row)
    return [first, second]


def demo():
    original = {"count": 4}
    copies = duplicate_row(original)
    copies[0]["count"] = 9
    return [copies[1]["count"], original["count"]]

def collect(label, labels=[]):
    labels.append(label)
    return list(labels)


def demo():
    first = collect("red")
    second = collect("blue")
    return [first, second]

def discount(total, percent=10):
    return total - percent


def demo():
    return discount(80, percent=25)

def join_pair(left, right, *, separator=":"):
    return left + separator + right


def demo():
    return join_pair("left", "right", separator="")
